def find_kth_number(m, n, k):
    def count_le(x):
        total = 0
        for i in range(1, m + 1):
            total += min(n, x // i)                # O(1) per row via the formula
        return total

    lo, hi = 1, m * n
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if count_le(mid) >= k:
            hi = mid                                  # enough entries <= mid, search smaller
        else:
            lo = mid + 1                               # not enough, search larger
    return lo

