public class Main {
    static long countLE(int m, int n, long x) {
        long total = 0;
        for (int i = 1; i <= m; i++) {
            total += Math.min(n, x / i);                  // O(1) per row via the formula
        }
        return total;
    }

    static int findKthNumber(int m, int n, int k) {
        long lo = 1, hi = (long) m * n;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (countLE(m, n, mid) >= k) hi = mid;           // enough entries, search smaller
            else lo = mid + 1;                                  // not enough, search larger
        }
        return (int) lo;
    }
}

