int findKthNumber(int m, int n, int k) {
    long long lo = 1, hi = (long long)m * n;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (countLE(m, n, mid) >= k) hi = mid;                    // enough entries, search smaller
        else lo = mid + 1;                                           // not enough, search larger
    }
    return (int) lo;
}
